#!/usr/bin/env bash
# Writes charts/cloudnative-app/values-dev.yaml from Terraform outputs.
# (Image TAGS are NOT written here: CI owns them, in values-images.yaml.)
# Usage: bash scripts/gen-values.sh
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
dev()    { ( cd "$ROOT/envs/dev"    && terraform output -raw "$1" ); }
shared() { ( cd "$ROOT/envs/shared" && terraform output -raw "$1" ); }

cat > "$ROOT/charts/cloudnative-app/values-dev.yaml" <<YAML
# GENERATED by scripts/gen-values.sh - safe to commit (endpoints and ARNs, no secrets)
api:
  image:
    repository: $(shared ecr_api_url)
frontend:
  image:
    repository: $(shared ecr_frontend_url)
data:
  dbHost: $(dev rds_address)
  dbSecretArn: $(dev rds_master_secret_arn)
  redisHost: $(dev redis_primary_endpoint)
irsa:
  apiRoleArn: $(dev api_role_arn)
YAML

echo "Wrote charts/cloudnative-app/values-dev.yaml"
